<script nonce="<?= htmlspecialchars((string) ($_SERVER['SENSE_CSP_NONCE'] ?? ''), ENT_QUOTES, 'UTF-8') ?>">document.addEventListener('DOMContentLoaded',()=>{const map={'/appearance':[['/content/home','Homepage','house'],['/content/navigation','Navigation','menu'],['/appearance/themes','Installed themes','panels-top-left']],'/content/home':[['/appearance','Appearance','palette'],['/content/navigation','Navigation','menu'],['/appearance/themes','Installed themes','panels-top-left']]};for(const [action,items] of Object.entries(map)){const form=document.querySelector(`form[action="${action}"]`),aside=form?.closest('.grid')?.querySelector('aside .card');if(!aside||aside.querySelector('.sensecms-section-nav'))continue;const nav=document.createElement('nav');nav.className='sensecms-section-nav';nav.innerHTML=items.map(([href,label,icon])=>`<a href="${href}"><span><i data-lucide="${icon}" class="mr-2 inline size-4 text-primary"></i>${label}</span><i data-lucide="chevron-right" class="size-4 text-default-400"></i></a>`).join('');aside.querySelector('.card-body')?.append(nav)}window.lucide?.createIcons()});</script>
<script nonce="<?= htmlspecialchars((string) ($_SERVER['SENSE_CSP_NONCE'] ?? ''), ENT_QUOTES, 'UTF-8') ?>">document.addEventListener('DOMContentLoaded',()=>{const icons=[['book-open','Book open'],['calendar-days','Calendar'],['chart-no-axes-combined','Growth'],['compass','Compass'],['earth','Earth'],['flame','Flame'],['globe','Globe'],['graduation-cap','Graduation'],['heart','Heart'],['house','Home'],['lightbulb','Idea'],['medal','Medal'],['moon-star','Moon star'],['music','Music'],['rocket','Rocket'],['shield-check','Shield'],['sparkles','Sparkles'],['star','Star'],['sun','Sun'],['trophy','Trophy'],['users','Community']],modal=document.createElement('dialog');modal.className='sensecms-icon-modal';modal.setAttribute('aria-label','Choose an icon');modal.innerHTML='<section><header><h3>Choose an icon</h3><button class="sensecms-icon-close" type="button" aria-label="Close">×</button></header><main><input class="sensecms-icon-search" type="search" aria-label="Search icons by name" placeholder="Search icons by name"><div class="sensecms-icon-grid"></div><p class="sensecms-icon-empty" hidden>No matching icons.</p></main></section>';document.body.append(modal);let active,opener,query=modal.querySelector('input'),grid=modal.querySelector('.sensecms-icon-grid'),empty=modal.querySelector('.sensecms-icon-empty'),render=()=>{const term=query.value.toLowerCase().trim(),found=icons.filter(([,label])=>label.toLowerCase().includes(term));grid.replaceChildren(...found.map(([value,label])=>{const item=document.createElement('button');item.type='button';item.className='sensecms-icon-option'+(active?.value===value?' is-selected':'');item.dataset.value=value;item.innerHTML='<i data-lucide="'+value+'"></i><span>'+label+'</span>';return item}));empty.hidden=!!found.length;window.lucide?.createIcons()},close=()=>{modal.close();opener?.focus()};icons.forEach(([value,label])=>document.querySelectorAll('select[name="popup_fact_icon[]"]').forEach(select=>{if(![...select.options].some(option=>option.value===value))select.add(new Option(label,value))}));document.querySelectorAll('select[name="popup_fact_icon[]"]').forEach(select=>{select.classList.add('sr-only');const trigger=document.createElement('button');trigger.type='button';trigger.className='sensecms-icon-trigger';const update=()=>{const name=icons.find(([value])=>value===select.value)||icons.find(([value])=>value==='sparkles');trigger.innerHTML='<span><i data-lucide="'+name[0]+'"></i>'+name[1]+'</span><i data-lucide="chevrons-up-down"></i>';window.lucide?.createIcons()};trigger.onclick=()=>{active=select;opener=trigger;query.value='';render();modal.showModal();query.focus()};select.addEventListener('change',update);select.insertAdjacentElement('afterend',trigger);update()});query.addEventListener('input',render);grid.addEventListener('click',event=>{const item=event.target.closest('[data-value]');if(!item||!active)return;active.value=item.dataset.value;active.dispatchEvent(new Event('change',{bubbles:true}));close()});modal.querySelector('.sensecms-icon-close').onclick=close;modal.addEventListener('click',event=>{if(event.target===modal)close()});modal.addEventListener('cancel',event=>{event.preventDefault();close()})});</script>
